//! „Über proAVA“: version, build, own licence (`LICENSE`, Business Source
//! License 1.1, shown in full on request) and the notices of all
//! third-party parts (`THIRD-PARTY-NOTICES`, generated by
//! `scripts/third_party_notices.py`). Any screen asks for it with
//! [`request`]; the host shows it above everything.

use eframe::egui::{self, RichText};

use crate::theme::Palette;
use crate::widgets;

/// Program symbol (blue tile with „A“), source `assets/icons/proava.svg`.
pub const ICON_PNG: &[u8] = include_bytes!("../../../assets/icons/proava-256.png");
/// Notices of all third-party parts, as shipped next to the program.
pub const THIRD_PARTY_NOTICES: &str = include_str!("../../../THIRD-PARTY-NOTICES");
/// proAVA's own licence (English text, binding), as shipped next to the program.
pub const LICENSE: &str = include_str!("../../../LICENSE");
/// The licence in one line (German summary; the English text binds).
pub const LICENSE_SUMMARY: &str = "Business Source License 1.1 – kommerzielle Nutzung erlaubt, \
     nicht als Produkt verkaufen oder als SaaS anbieten; ab 20.11.2030 AGPL-3.0";

/// The disclaimer of warranty, English (shown first) …
pub const WARRANTY_EN: &str =
    "proAVA comes with ABSOLUTELY NO WARRANTY, to the extent permitted by \
     applicable law. Use at your own risk; check all results (LV, quantities, prices, totals, GAEB \
     files) before you rely on them.";
/// … and German, with the liability for intent and gross negligence kept
/// (a full exclusion would not hold under German law). Also in README,
/// handbook, LIESMICH.txt and on the empty start page; not in LICENSE.
pub const WARRANTY_DE: &str = "proAVA wird ohne jegliche Gewährleistung bereitgestellt, soweit \
     gesetzlich zulässig. Die Nutzung erfolgt auf eigenes Risiko; alle Ergebnisse (LV, Mengen, \
     Preise, Summen, GAEB-Dateien) vor Verwendung prüfen. Die Haftung für Vorsatz und grobe \
     Fahrlässigkeit bleibt unberührt.";

/// Height of the dialog besides a text view (header, disclaimer, buttons).
const WINDOW_REST: f32 = 420.0;

/// What the dialog shows below the header.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Shown {
    Overview,
    Notices,
    License,
}

pub const VERSION: &str = env!("CARGO_PKG_VERSION");
pub const GIT_COMMIT: &str = env!("PROAVA_GIT_COMMIT");
pub const BUILD_DATE: &str = env!("PROAVA_BUILD_DATE");

const REQUEST_ID: &str = "proava_about_request";

/// Ask the host to open „Über proAVA“ (from a menu or a link).
pub fn request(ctx: &egui::Context) {
    ctx.data_mut(|data| data.insert_temp(egui::Id::unique(REQUEST_ID), true));
}

/// Whether someone asked for the dialog since the last call (clears the request).
pub fn take_request(ctx: &egui::Context) -> bool {
    ctx.data_mut(|data| data.remove_temp::<bool>(egui::Id::unique(REQUEST_ID)))
        .unwrap_or(false)
}

/// The window icon for eframe.
pub fn window_icon() -> Option<egui::IconData> {
    let image = image::load_from_memory_with_format(ICON_PNG, image::ImageFormat::Png)
        .ok()?
        .into_rgba8();
    let (width, height) = image.dimensions();
    Some(egui::IconData {
        rgba: image.into_raw(),
        width,
        height,
    })
}

/// Main components named in the dialog (all others are in the notices).
const COMPONENTS: [(&str, &str); 7] = [
    ("Typst (PDF-Satz)", "Apache-2.0"),
    ("egui / eframe (Oberfläche)", "MIT oder Apache-2.0"),
    ("Liberation Sans (Schrift)", "SIL Open Font License 1.1"),
    (
        "Ubuntu, Noto, Hack, Emoji-Icon-Font (Schriften von egui)",
        "Ubuntu Font Licence / OFL-1.1 / MIT",
    ),
    ("quick-xml (GAEB DA XML)", "MIT"),
    ("rust_decimal (Beträge)", "MIT"),
    ("zip (Projektdatei, Sicherung)", "MIT"),
];

pub struct AboutDialog {
    icon: Option<egui::TextureHandle>,
    shown: Shown,
    filter: String,
    lines: Vec<&'static str>,
}

impl Default for AboutDialog {
    fn default() -> Self {
        Self::new()
    }
}

impl AboutDialog {
    pub fn new() -> Self {
        Self {
            icon: None,
            shown: Shown::Overview,
            filter: String::new(),
            lines: THIRD_PARTY_NOTICES.lines().collect(),
        }
    }

    /// Number of third-party crates named in the notices.
    pub fn crate_count() -> usize {
        THIRD_PARTY_NOTICES
            .lines()
            .find_map(|line| {
                line.strip_prefix("Crates (")?
                    .strip_suffix(')')?
                    .parse()
                    .ok()
            })
            .unwrap_or(0)
    }

    /// Draws the dialog; false when it was closed.
    pub fn show(&mut self, ui: &mut egui::Ui, palette: &Palette) -> bool {
        let ctx = ui.ctx().clone();
        let icon = self.icon.get_or_insert_with(|| {
            let image = window_icon().map(|icon| {
                egui::ColorImage::from_rgba_unmultiplied(
                    [icon.width as usize, icon.height as usize],
                    &icon.rgba,
                )
            });
            ctx.load_texture(
                "proava_about_icon",
                image.unwrap_or_else(|| egui::ColorImage::new([1, 1], vec![palette.accent])),
                egui::TextureOptions::LINEAR,
            )
        });
        let icon = icon.id();
        let mut open = true;
        let width = if self.shown == Shown::Overview {
            560.0
        } else {
            820.0
        };
        let (_, close) = widgets::modal(ui, palette, width, |ui| {
            ui.horizontal(|ui| {
                ui.add(egui::Image::new((icon, egui::vec2(64.0, 64.0))));
                ui.add_space(10.0);
                ui.vertical(|ui| {
                    ui.label(
                        RichText::new("proAVA")
                            .size(22.0)
                            .strong()
                            .color(palette.text),
                    );
                    ui.label(
                        RichText::new("Ausschreibung · Vergabe · Abrechnung")
                            .size(12.5)
                            .color(palette.text_dim),
                    );
                    ui.label(
                        RichText::new(format!(
                            "Version {VERSION} · Build {BUILD_DATE} · Commit {GIT_COMMIT}"
                        ))
                        .size(12.5)
                        .color(palette.text),
                    );
                });
            });
            ui.add_space(12.0);
            ui.label(
                RichText::new("© 2026 Oliver Hagmann")
                    .size(12.5)
                    .color(palette.text),
            );
            ui.label(
                RichText::new(LICENSE_SUMMARY)
                    .size(12.5)
                    .color(palette.text),
            );
            ui.label(
                RichText::new(
                    "Verbindlich ist der englische Lizenztext: Datei LICENSE neben dem Programm \
                     (Windows LICENSE.txt), „Lizenz anzeigen“ unten und im Handbuch.",
                )
                .size(11.5)
                .color(palette.text_dim),
            );
            ui.add_space(10.0);
            if self.shown == Shown::Overview {
                ui.label(
                    RichText::new(format!(
                        "Enthält freie Bestandteile Dritter ({} Crates, dazu Schriften):",
                        Self::crate_count()
                    ))
                    .size(12.5)
                    .color(palette.text_dim),
                );
                egui::Grid::new("about_components")
                    .num_columns(2)
                    .spacing([16.0, 4.0])
                    .show(ui, |ui| {
                        for (name, license) in COMPONENTS {
                            ui.label(RichText::new(name).size(12.5).color(palette.text));
                            ui.label(RichText::new(license).size(12.5).color(palette.text_dim));
                            ui.end_row();
                        }
                    });
            }
            ui.add_space(8.0);
            match self.shown {
                Shown::Overview => {}
                Shown::Notices => self.notices_view(ui, palette),
                Shown::License => license_view(ui, palette),
            }
            ui.add_space(8.0);
            warranty(ui, palette);
            ui.add_space(8.0);
            ui.horizontal(|ui| {
                let (license, notices) = match self.shown {
                    Shown::License => ("Lizenz ausblenden", "Alle Lizenzhinweise anzeigen"),
                    Shown::Notices => ("Lizenz anzeigen", "Hinweise ausblenden"),
                    Shown::Overview => ("Lizenz anzeigen", "Alle Lizenzhinweise anzeigen"),
                };
                if ui.button(license).clicked() {
                    self.shown = if self.shown == Shown::License {
                        Shown::Overview
                    } else {
                        Shown::License
                    };
                }
                if ui.button(notices).clicked() {
                    self.shown = if self.shown == Shown::Notices {
                        Shown::Overview
                    } else {
                        Shown::Notices
                    };
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if widgets::accent_button(ui, palette, "Schließen") {
                        open = false;
                    }
                });
            });
        });
        open && !close
    }

    fn notices_view(&mut self, ui: &mut egui::Ui, palette: &Palette) {
        crate::widgets::row(ui, |ui| {
            ui.label(RichText::new("Suchen").size(12.0).color(palette.text_dim));
            ui.add(egui::TextEdit::singleline(&mut self.filter).desired_width(260.0));
            ui.label(
                RichText::new("Datei THIRD-PARTY-NOTICES liegt auch neben dem Programm.")
                    .size(11.5)
                    .color(palette.text_dim),
            );
        });
        let needle = self.filter.trim().to_lowercase();
        let shown: Vec<&str> = if needle.is_empty() {
            self.lines.clone()
        } else {
            // A hit on a crate line brings its indented details (licence, source).
            let mut shown = Vec::new();
            let mut details = false;
            for line in &self.lines {
                let indented = line.starts_with(' ');
                if line.to_lowercase().contains(&needle) {
                    shown.push(*line);
                    details = !indented;
                } else if details && indented && !line.trim().is_empty() {
                    shown.push(*line);
                } else {
                    details = false;
                }
            }
            shown
        };
        let row_height = ui.text_style_height(&egui::TextStyle::Monospace);
        // Fits the window: header, search, disclaimer and buttons take about
        // 400 px.
        let height = (ui.ctx().content_rect().height() - WINDOW_REST).clamp(160.0, 520.0);
        egui::Frame::new()
            .stroke(egui::Stroke::new(1.0, palette.line))
            .corner_radius(egui::CornerRadius::same(6))
            .inner_margin(egui::Margin::same(8))
            .show(ui, |ui| {
                egui::ScrollArea::both()
                    .max_height(height)
                    .auto_shrink([false, false])
                    .show_rows(ui, row_height, shown.len(), |ui, range| {
                        for line in &shown[range] {
                            ui.label(
                                RichText::new(*line)
                                    .monospace()
                                    .size(11.5)
                                    .color(palette.text),
                            );
                        }
                    });
            });
    }
}

/// The disclaimer of warranty (English, then German), clearly visible: in a
/// frame in the warning colour, above the licence buttons.
pub fn warranty(ui: &mut egui::Ui, palette: &Palette) {
    egui::Frame::new()
        .stroke(egui::Stroke::new(1.0, palette.warn))
        .corner_radius(egui::CornerRadius::same(6))
        .inner_margin(egui::Margin::same(8))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.label(
                RichText::new(WARRANTY_EN)
                    .font(crate::fonts::bold(12.0))
                    .color(palette.text),
            );
            ui.add_space(4.0);
            ui.label(RichText::new(WARRANTY_DE).size(12.0).color(palette.text));
        });
}

/// proAVA's licence text (monospace, scrolls; the window keeps its size).
fn license_view(ui: &mut egui::Ui, palette: &Palette) {
    let height = (ui.ctx().content_rect().height() - WINDOW_REST).clamp(160.0, 520.0);
    egui::Frame::new()
        .stroke(egui::Stroke::new(1.0, palette.line))
        .corner_radius(egui::CornerRadius::same(6))
        .inner_margin(egui::Margin::same(8))
        .show(ui, |ui| {
            egui::ScrollArea::both()
                .id_salt("about_license")
                .max_height(height)
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    for line in LICENSE.lines() {
                        ui.label(
                            RichText::new(line)
                                .monospace()
                                .size(11.5)
                                .color(palette.text),
                        );
                    }
                });
        });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn icon_and_notices_are_built_in() {
        let icon = window_icon().expect("Symbol lesbar");
        assert_eq!((icon.width, icon.height), (256, 256));
        assert!(AboutDialog::crate_count() > 100);
        for needed in [
            "typst 0.15",
            "egui 0.37",
            "Liberation Sans",
            "Apache License",
            "SIL OPEN FONT LICENSE",
        ] {
            assert!(
                THIRD_PARTY_NOTICES.contains(needed)
                    || THIRD_PARTY_NOTICES
                        .to_uppercase()
                        .contains(&needed.to_uppercase()),
                "{needed} fehlt in THIRD-PARTY-NOTICES"
            );
        }
        assert!(!GIT_COMMIT.is_empty() && BUILD_DATE.len() == 10);
    }

    /// The licence is built in and matches the summary in the dialog.
    #[test]
    fn the_own_licence_is_built_in() {
        assert!(LICENSE.starts_with("Business Source License 1.1"));
        for needed in [
            "Licensor:             Oliver Hagmann",
            "Change Date:          2030-11-20",
            "GNU Affero General Public License v3.0 or later",
            "you must purchase a",
        ] {
            assert!(LICENSE.contains(needed), "{needed} fehlt in LICENSE");
        }
        assert!(LICENSE_SUMMARY.contains("20.11.2030"));
        // The full standard text, the grant only grants (2026-11-20); line
        // breaks of the text file do not count.
        let license = LICENSE.split_whitespace().collect::<Vec<_>>().join(" ");
        for needed in [
            "MariaDB hereby grants you permission to use this License’s text",
            "Covenants of Licensor",
            "4. Not to modify this License in any other way.",
            "Notice",
            "License text copyright (c) 2017 MariaDB plc, All Rights Reserved.",
            "as a primary component of a paid software bundle",
            "This Additional Use Grant does not include:",
        ] {
            assert!(license.contains(needed), "{needed} fehlt in LICENSE");
        }
        assert!(
            !license.contains("You may NOT"),
            "der Grant verbietet nichts zusätzlich"
        );
        assert!(
            !license.contains("NO WARRANTY"),
            "der Hinweis steht nicht in LICENSE"
        );
        assert!(WARRANTY_DE.contains("Vorsatz und grobe Fahrlässigkeit"));
        assert!(THIRD_PARTY_NOTICES.contains("Business Source License 1.1"));
    }
}
